const page=document.body.dataset.page, q=new URLSearchParams(location.search), el=id=>document.querySelector(id);
const time=value=>new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',dateStyle:'short',timeStyle:'short'}).format(new Date(value));
const date=value=>new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',dateStyle:'short'}).format(new Date(value+'T12:00:00Z'));
const shell=(title,kicker='Série A · Brasil')=>`<header class="top"><div class="wrap"><a class="brand" href="index.html"><span class="mark">↗</span>FUTRanking</a><nav><a href="ranking.html">Ranking</a><a href="resultados.html">Resultados</a><a href="proximos-jogos.html">Próximos jogos</a><a href="metodo.html">Método</a></nav><span class="pill">${kicker}</span></div></header><main class="wrap page"><div class="eyebrow">${kicker}</div><h1>${title}</h1><div id="content"></div></main><footer class="foot"><div class="wrap">FUTRanking · Glicko-2 para o futebol brasileiro</div></footer>`;
const game=(m,fixture=false)=>`<div class="row"><span class="date">${fixture?time(m.scheduled_at):date(m.played_at)}</span><span class="home">${m.home_team}<small class="rating">${fixture?`${m.home_rating.toFixed(1)} · ${m.home_favoritism}%`:`${m.home_rating_after?.toFixed(1)??''} ${m.home_rating_effect>=0?'+':''}${m.home_rating_effect?.toFixed(1)??''}`}</small></span><strong class="score">${fixture?'×':`${m.home_goals}–${m.away_goals}`}</strong><span class="away">${m.away_team}<small class="rating">${fixture?`${m.away_rating.toFixed(1)} · ${m.away_favoritism}%`:`${m.away_rating_after?.toFixed(1)??''} ${m.away_rating_effect>=0?'+':''}${m.away_rating_effect?.toFixed(1)??''}`}</small></span></div>`;
fetch('./data/ranking.json').then(r=>r.json()).then(data=>{if(page==='ranking'){document.body.innerHTML=shell('Ranking');el('#content').innerHTML=`<p>Força estimada, atualizada até ${date(data.period_date)}. Clique em um clube.</p><section class="panel">${data.teams.map(t=>`<a class="row rank" href="clube.html?time=${encodeURIComponent(t.name)}"><span>${t.position}º</span><b>${t.name}</b><strong>${t.rating.toFixed(1)}</strong><span>RD ${t.rd.toFixed(1)}</span></a>`).join('')}</section>`;}if(page==='resultados'){document.body.innerHTML=shell('Últimos resultados','Transparência');el('#content').innerHTML=`<p>Rating após o ciclo e impacto estimado daquele jogo.</p><section class="panel">${data.matches.slice(0,30).map(m=>game(m)).join('')}</section>`;}if(page==='fixtures'){document.body.innerHTML=shell('Próximos jogos','Agenda');el('#content').innerHTML=`<p>Horários em Brasília. Percentuais representam favoritismo Glicko-2 com mando de campo.</p><section class="panel">${data.fixtures.map(m=>game(m,true)).join('')||'<p style="padding:20px">Nenhum jogo futuro disponível.</p>'}</section>`;}if(page==='club'){const name=q.get('time'),team=data.teams.find(t=>t.name===name);if(!team){document.body.innerHTML=shell('Clube não encontrado');return}const matches=data.matches.filter(m=>m.home_team===name||m.away_team===name).slice(0,12),fixtures=data.fixtures.filter(m=>m.home_team===name||m.away_team===name),p=team.performance;document.body.innerHTML=shell(name,'Perfil do clube');el('#content').innerHTML=`<a class="back" href="ranking.html">← Voltar ao ranking</a><div class="stats"><div class="stat"><b>${team.position}º</b><span>posição</span></div><div class="stat"><b>${team.rating.toFixed(1)}</b><span>rating</span></div><div class="stat"><b>${p.games}</b><span>jogos</span></div><div class="stat"><b>${p.wins}-${p.draws}-${p.losses}</b><span>V-E-D</span></div><div class="stat"><b>${p.goals_for}:${p.goals_against}</b><span>gols</span></div><div class="stat"><b>${p.points}</b><span>pontos</span></div></div><h2>Próximos fixtures</h2><section class="panel">${fixtures.map(m=>game(m,true)).join('')||'<p style="padding:20px">Nenhum fixture futuro disponível.</p>'}</section><h2>Últimos resultados</h2><section class="panel">${matches.map(m=>game(m)).join('')}</section>`;}if(page==='method'){document.body.innerHTML=shell('Método','Como funciona');el('#content').innerHTML='<p>O FUTRanking usa Glicko-2. O rating estima força, o RD expressa a incerteza e a volatilidade captura mudanças de desempenho.</p><h2>Atualização semanal</h2><p>Jogos de uma mesma semana são calculados juntos, evitando uma ordem artificial. O mando entra na expectativa pré-jogo. Fixtures aparecem apenas como projeção e jamais alteram o rating antes do placar final.</p>';}}).catch(()=>document.body.innerHTML=shell('Dados indisponíveis'));

